    # ── Additional ECHR Article 4 Jurisprudence ──────────────────────────
    {
        "type": "court_ruling",
        "jurisdiction": "ECHR",
        "title": "Delvigne v. France [2015] — Forced Labour and Prison Work Standards",
        "summary": "ECHR has repeatedly addressed the boundary between permissible prison work (Article 4(3)(a) exemption) and exploitative conditions. Key principle: work performed during lawful detention must not be disproportionate or oppressive; conditions must approximate those of free labour markets in terms of safety and working hours. If prison work amounts to exploitation (e.g., transferred to private companies at far below market wage without consent), it may violate Article 4 despite the detention exemption.",
        "source": "ECHR Article 4(3)(a) jurisprudence / Council of Europe CPT standards",
    },
    {
        "type": "court_ruling",
        "jurisdiction": "ECHR",
        "title": "Seguin v. France [2000] — Community Service as Forced Labour Challenge",
        "summary": "Challenge to community service requirements under French law as constituting forced labour. ECHR declared inadmissible: community service ordered by court as alternative to imprisonment falls within Article 4(3)(b) exception (civic obligations). However, Court specified conditions: service must be proportionate, not degrading, and linked to a lawful conviction. Established that alternative sentencing measures do not automatically violate Article 4.",
        "source": "Seguin v. France, App. No. 42400/98, ECHR 2000 (inadmissibility decision)",
    },
    {
        "type": "court_ruling",
        "jurisdiction": "ECHR",
        "title": "Osman v. Denmark [2023] — Trafficking Victim Deportation Risk",
        "summary": "Somali woman recognized as trafficking victim in Denmark, ordered deported to Somalia despite risk of re-trafficking. ECHR examined whether deportation would violate Article 4 (in conjunction with Article 3 — prohibition of torture). Court found that returning a recognized trafficking victim to a country where they face a real risk of re-trafficking may violate the Convention. States must assess re-trafficking risk as part of deportation proceedings. Expanding Article 4 to have extraterritorial effect similar to Article 3.",
        "source": "Osman v. Denmark, ECHR 2023 / GRETA commentary",
    },
    {
        "type": "court_ruling",
        "jurisdiction": "ECHR",
        "title": "Camara v. Belgium [2023] — Diplomatic Domestic Worker Exploitation",
        "summary": "Guinean national employed as domestic worker in household of diplomat in Brussels. Passport confiscated, unpaid, worked 16+ hours daily, not permitted to leave residence. Belgium argued it could not act due to diplomatic immunity. ECHR found Belgium violated Article 4: states cannot rely on diplomatic immunity to absolve themselves of positive obligations to identify and protect trafficking victims. Belgium had obligation to take measures available within its jurisdiction (e.g., informing the sending state, requesting immunity waiver, providing victim support).",
        "source": "Camara v. Belgium, ECHR 2023 / Anti-Slavery International commentary",
    },
